function pc16AutoFitV21_65(){
  // A maximize/restore on Windows can arrive in several steps. Re-measure
  // repeatedly so a window that was small cannot remain small after maximize.
  [0,30,80,160,300,500,800,1200,1800].forEach(function(ms){
    setTimeout(function(){requestAnimationFrame(scaleStage)},ms);
  });
}

