async function loadClients(force){
  if(!force&&!st.clients.length){
    if(pc16RestoreGlobalCache())renderAll();
  }
  try{
    let changed=false,clients;
    try{clients=await gs('obtenirDossiersClientsPCLeger',[!!force])}
    catch(_){clients=await gs('obtenirDossiersClients',[!!force])}
    if(Array.isArray(clients)){
      const before=JSON.stringify((st.clients||[]).map(c=>[c.id,c.nom,c.dateModification||'']));
      const after=JSON.stringify(clients.map(c=>[c.id,c.nom,c.dateModification||'']));
      if(before!==after){st.clients=clients;changed=true}
      st.lastClientsSync=Date.now();
    }
    const ids=st.clients.map(c=>c.id);
    const jobs=[
      gs('obtenirResumesConformiteClientsCDQ',[ids]).catch(()=>null),
      gs('obtenirRapportsRecentsPC',[40,!!force]).catch(()=>null)
    ];
    const result=await Promise.all(jobs);
    if(result[0]){
      if(JSON.stringify(st.summaries||{})!==JSON.stringify(result[0]))changed=true;
      st.summaries=result[0];
    }
    if(Array.isArray(result[1])){
      const before=JSON.stringify((st.recent||[]).map(f=>[f.id,f.nom,f.dateModification||'',f.typeBalance||'']));
      const after=JSON.stringify(result[1].map(f=>[f.id,f.nom,f.dateModification||'',f.typeBalance||'']));
      if(before!==after)changed=true;
      st.recent=result[1];
    }
    if(!st.selected&&st.recent.length)st.selected=st.recent[0];
    st.lastClientsSync=Date.now();
    pc16SaveGlobalCache();
    if(changed)renderAll();
  }catch(e){toast(e&&e.message||e,true)}
}

